INSERT INTO events(event_id,calendar_id,summary,description,location,start_dt,end_dt,all_day,status,created_at,updated_at,recurrence_rule,parent_event_id) VALUES ('evt_student_3eb32fb9','cal_wheelchair_main','Research Group Discussion | Experimental Progress Discussion','The research group discussion will be held in the laboratory building at Donghu University. This session will focus on discussing experimental progress; Shen Wenxi must first check the experimental progress, then confirm the division of responsibilities and next week’s milestones.','Donghu University Experimental Building','2026-07-23T00:00:00+08:00','2026-07-24T00:00:00+08:00',1,'confirmed','2026-07-12T16:00:00Z','2026-07-12T16:00:00Z',NULL,NULL);
