INSERT INTO events(event_id,calendar_id,summary,description,location,start_dt,end_dt,all_day,status,created_at,updated_at,recurrence_rule,parent_event_id) VALUES ('evt_student_3a2c79d5','cal_wheelchair_main','Financial Aid Materials Processing | Application List Communication','The Student Affairs Center has reserved time for scholarship and financial aid materials processing, with the topic of discussing the application checklist. Before the meeting ends, the application checklist must be checked, and the method for submitting missing proof documents must be recorded and confirmed.','Student Affairs Center','2026-06-20T18:40:00+08:00','2026-06-20T19:40:00+08:00',0,'confirmed','2026-06-08T10:40:00Z','2026-06-08T10:40:00Z',NULL,NULL);
INSERT INTO events(event_id,calendar_id,summary,description,location,start_dt,end_dt,all_day,status,created_at,updated_at,recurrence_rule,parent_event_id) VALUES ('evt_student_c5097d4b','cal_wheelchair_main','Library Materials Organization | Discussion of Borrowed Materials','For this library materials organization task, Shen Wenxi handled matters concerning discussion of borrowed materials. After arriving at Donghu University Library, she first returned the overdue books and, before leaving, confirmed that she had downloaded the course-assigned readings.','Donghu University Library','2026-06-17T15:40:00+08:00','2026-06-17T17:40:00+08:00',0,'confirmed','2026-06-01T07:40:00Z','2026-06-01T07:40:00Z',NULL,NULL);
INSERT INTO events(event_id,calendar_id,summary,description,location,start_dt,end_dt,all_day,status,created_at,updated_at,recurrence_rule,parent_event_id) VALUES ('evt_student_5fda9782','cal_wheelchair_main','Rehabilitation Training | Training Record Exchange','The rehabilitation training associated with the training record for communication is scheduled in the rehabilitation room of the school hospital; in addition to completing the routine training that day, time must also be set aside to adjust the intensity based on the day''s condition.','University Hospital Rehabilitation Room','2026-08-02T00:00:00+08:00','2026-08-03T00:00:00+08:00',1,'confirmed','2026-07-19T16:00:00Z','2026-07-19T16:00:00Z',NULL,NULL);
INSERT INTO events(event_id,calendar_id,summary,description,location,start_dt,end_dt,all_day,status,created_at,updated_at,recurrence_rule,parent_event_id) VALUES ('evt_student_9889305f','cal_wheelchair_main','Specialized course Q&A｜Course question discussion','The personal calendar marks the discussion of course-related questions as a subject-course Q&A task; the college teaching building can be used to organize the course questions, followed by completing the missing derivation steps in the homework.','College Teaching Building','2026-08-14T13:00:00+08:00','2026-08-14T14:00:00+08:00',0,'confirmed','2026-07-27T05:00:00Z','2026-07-27T05:00:00Z',NULL,NULL);
INSERT INTO events(event_id,calendar_id,summary,description,location,start_dt,end_dt,all_day,status,created_at,updated_at,recurrence_rule,parent_event_id) VALUES ('evt_student_6073b564','cal_wheelchair_main','College Lecture｜Lecture Notes Exchange','The college lecture will take place in the college lecture hall, focusing on the exchange of lecture notes. Shen Wenxi needs to record the key points of the lecture first, then set aside time to enter and leave the venue.','College Lecture Hall','2026-07-02T08:10:00+08:00','2026-07-02T09:10:00+08:00',0,'confirmed','2026-06-08T00:10:00Z','2026-06-08T00:10:00Z',NULL,NULL);
INSERT INTO events(event_id,calendar_id,summary,description,location,start_dt,end_dt,all_day,status,created_at,updated_at,recurrence_rule,parent_event_id) VALUES ('evt_student_8b31d9fa','cal_wheelchair_main','Laboratory Instrument Booking｜Instrument Time Slot Discussion','As part of discussions about instrument time slots, arrange one reservation for a laboratory instrument at the Donghu University laboratory building. The checklist includes “Check the reservation time slot” and “Record the equipment-use requirements.”','Donghu University Experimental Building','2026-07-01T08:10:00+08:00','2026-07-01T08:55:00+08:00',0,'confirmed','2026-05-29T00:10:00Z','2026-05-29T00:10:00Z',NULL,NULL);
INSERT INTO events(event_id,calendar_id,summary,description,location,start_dt,end_dt,all_day,status,created_at,updated_at,recurrence_rule,parent_event_id) VALUES ('evt_student_fcb5c82d','cal_wheelchair_main','Course Group Meeting | Presentation Materials Discussion','The college teaching building has been reserved for the course group meeting. The agenda is to exchange presentation materials, and before the meeting ends, the presentation materials must be consolidated and the group’s speaking order recorded and confirmed.','College Teaching Building','2026-06-20T00:00:00+08:00','2026-06-21T00:00:00+08:00',1,'confirmed','2026-05-25T16:00:00Z','2026-05-25T16:00:00Z',NULL,NULL);
